# Over ssh the visible prompt leads with the short hostname (e.g. `du-t450s ~ $`) so a
# remote terminal is obvious at a glance; local prompts keep the clock.
# >>> shguard modes=source (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'aliases.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  source) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: source; pipe callers set SHGUARD_MODE=pipe)\n' 'aliases.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
if [ -n "${SSH_CONNECTION:-}" ]; then
    export PS1='\[\033]0;\u@\h \d \t\a\]\[\033[00;36m\]\h \w \$ \[\033[00m\]'
else
    export PS1='\[\033]0;\u@\h \d \t\a\]\[\033[00;36m\]\t \w \$ \[\033[00m\]'
fi

# A client TERM this host has no terminfo for (e.g. xterm-ghostty over a raw
# ssh) breaks clear/tput; fall back to a universally known entry.
if command -v infocmp >/dev/null 2>&1 && ! infocmp "$TERM" >/dev/null 2>&1; then
    export TERM=xterm-256color
fi

# CONFIG VARIABLES
code_path="$HOME/code/"
down_path="$HOME/Downloads"
ssh_cmd="ssh"
work_user="username"
EXTERNAL_OUTPUT="DP-1-3"
INTERNAL_OUTPUT="eDP-1-1"

# https://github.com/ElectricRCAircraftGuy/eRCaGuy_hello_world/blob/master/bash/get_script_path.sh
here=$(dirname "$(realpath "${BASH_SOURCE[0]}")")

if [ -f "$here/config.sh" ] ; then
	# Optional machine-local overrides are deliberately not tracked.
	# shellcheck source=/dev/null
	source "$here/config.sh"
fi

# typing out the options every time gets old
_comp () {
	complete -o nospace -o filenames -F "_$1" "$1"
}

# echo messes up some function returns
debug () {
	echo "$*" >> /tmp/debug
}

# Directory-offset helpers: cd relative to a fixed base, forwarding an
# optional subdirectory argument. Bases are keyed by command name so the
# shared completion function below can look them up the same way.
_cd_offset () {
	cd "$1/${2:-}" || return
}

declare -A _cd_base=(
	[..]='..'
	[...]='../..'
	[down]="$down_path"
	[code]="$code_path"
)

.. () { _cd_offset "${_cd_base[..]}" "${1:-}"; }
... () { _cd_offset "${_cd_base[...]}" "${1:-}"; }
down () { _cd_offset "${_cd_base[down]}" "${1:-}"; }
code () { _cd_offset "${_cd_base[code]}" "${1:-}"; }

# shared completion: looks up the base for the requested command name.
# genpath prints one candidate per line, each carrying the typed directory
# prefix, so a name with spaces stays one candidate and readline never
# replaces the prefix with an empty common stem. -o filenames re-escapes.
_cd_complete () {
	mapfile -t COMPREPLY < <(genpath "${_cd_base[$1]}" "${COMP_WORDS[COMP_CWORD]}")
}
_.. () { _cd_complete ..; return 0; }
_... () { _cd_complete ...; return 0; }
_down () { _cd_complete down; return 0; }
_code () { _cd_complete code; return 0; }

for _cd_name in .. ... down code; do
	_comp "$_cd_name"
done
unset _cd_name

# completion generator for offset paths: candidates are the subdirectories
# of <base>/<typed prefix>, each printed on its own line as <typed
# prefix>/<name>/ so the caller's completion never loses what was typed.
genpath () {
	local base cur dir file name
	base=$1
	cur=$2
	# readline hands -F completers the raw word; drop its backslash escapes.
	cur=${cur//\\/}

	if [[ "$cur" == */* ]]; then
		dir=${cur%/*}/
		file=${cur##*/}
	else
		dir=''
		file=$cur
	fi

	[[ -d "$base/$dir" ]] || return 0
	while IFS= read -r -d '' name; do
		[[ "$name" == "$file"* ]] || continue
		printf '%s%s/\n' "$dir" "$name"
	done < <(find "$base/$dir" -mindepth 1 -maxdepth 1 -type d -printf '%f\0' | sort -z)
}

highfile () {
	local max=0
	local path name n
	path="${1:-./}"

	while IFS= read -r name; do
		if [[ "$name" =~ ^([0-9]+) ]]; then
			n=$((10#${BASH_REMATCH[1]}))
			((n > max)) && max=$n
		fi
	done < <(find "$path" -mindepth 1 -maxdepth 1 -printf '%f\n')

	echo "High: $max"
	max=$((max + 1))
	echo "Next: $max"
}

ajoin () {
	local out="$2"

	for item in "${@:3}"; do
		out="${out}${1}${item}"
	done

	echo "$out"
}

alias ll="ls -alF --color=auto"
alias llr="ls -alFR --color=auto"

# grep shortcuts
grep_options=( -iInR --exclude={*.d,*-bundle.js,*.map,*.min.js,*.min.css,*~,*.log,*.pyhistory} \
--exclude-dir={\
.apm,\
.deps,\
.git,\
.node-gyp,\
autom4te.cache,\
dist,\
node_modules,\
uploads,\
src-min-noconflict,\
venv\
} )

# raw grep (no excludes)
ga () {
	local path
	path="${2:-./}"

	grep -iIRP "${grep_options[@]}" "$1" "$path"
}
gac () {
	local path
	path="${2:-./}"

	grep -iIRPc "${grep_options[@]}" "$1" "$path"
}

# POSIX character classes can be a pain, especially if you forget egrep uses them
gp () {
	local path
	path="${2:-./}"

	grep -P "${grep_options[@]}" "$1" "$path"
}
gpc () {
	local path
	path="${2:-./}"

	grep -Pc "${grep_options[@]}" "$1" "$path" | grep -E ':[^0]'
}
gpw () {
	local path
	path="${2:-./}"

	grep -P "${grep_options[@]}" "\b$1\b" "$path"
}

# shortcut for mass rewrites
rall () {
	if [ "$#" -lt 2 ]; then
		set -- "${1:-}" ''
	fi

	find . -type f | grep -Ev '.git|node_modules|uploads|.png|.jpg|.jpeg' | xargs -d '\n' sed -i -r -e "s/$1/$2/g"
}

# mass permission changes
dirperm () {
	local path
	path="${1:-.}"

	find "$path" -type d -exec chmod 755 {} +
}

fileperm () {
	local path
	path="${1:-.}"

	find "$path" -type f -exec chmod 644 {} +
}

alias pingg="ping 8.8.8.8"

mydir () {
	local group
	group=$(id -g -n "$USER")

	sudo mkdir -p "$1"
	sudo chown "$USER":"$group" "$1"
}

movie_on () {
	xset -dpms s off
}
movie_off () {
	xset -dpms s on
}

tarc () {
	tar -zcvf "$1.tar.gz" "$1"
}
tarx () {
	tar -zxvf "$1"
}
complete -o nospace -F "_tar" "tar"

trackfix () {
	rename s/Track\ // -- *
	rename -v 's/^(\d)\./0$1./' -- *
}
trackconv () {
	local -a tracks=()
	mapfile -t tracks < <(find . -mindepth 1 -maxdepth 1 -printf '%f\n')

	for t in "${tracks[@]}"; do
		avconv -i "$t" "$t.mp3"
	done
}
mp3dir () {
	mkdir -p "$1-mp3"
	mv "$1"/*.mp3 "$1-mp3/."
}

gigs () {
	local path
	path="${1:-/}"

	du -h -t 1G "$path" 2> /dev/null
}

alias pow="sudo poweroff"

alias es="setxkbmap es"
alias en="setxkbmap us"

timer () {
	local MIN
	MIN="${1:-1}"

	for ((i=MIN*60; i>=0; i--)); do
		echo -ne "\r$(date -d"0+$i sec" +%H:%M:%S)"
		sleep 1
	done
}

# HOME is intentionally captured when the alias chain is sourced.
# shellcheck disable=SC2139
alias xres="xrdb -merge $HOME/.Xresources"

external () {
    xrandr --verbose --output "$EXTERNAL_OUTPUT" --auto --output "$INTERNAL_OUTPUT" --off
	xrandr --newmode "1920x1080_60.00"  173.00  1920 2048 2248 2576  1080 1083 1088 1120 -hsync +vsync 2> /dev/null || true
    xrandr --addmode "$EXTERNAL_OUTPUT" 1920x1080_60.00
    xrandr --output "$EXTERNAL_OUTPUT" --mode "1920x1080_60.00"
}
internal () {
    xrandr --output "$INTERNAL_OUTPUT" --auto --output "$EXTERNAL_OUTPUT" --off
    xrandr --newmode "1920x1080_60.00"  173.00  1920 2048 2248 2576  1080 1083 1088 1120 -hsync +vsync 2> /dev/null || true
    xrandr --addmode "$INTERNAL_OUTPUT" 1920x1080_60.00
    xrandr --output "$INTERNAL_OUTPUT" --mode "1920x1080_60.00"
}

playdir() {
	# options don't seem to work w/o interface?
	# --key-play-pause " " --key-next "d" --key-prev "a"
	cvlc --play-and-exit ./*.mp3
}

alias gdbr="gdb -ex r"
# The resolved path is intentionally captured when the alias chain is sourced.
# shellcheck disable=SC2139
alias gdbx="gdb -x $here/dotfiles/gdb/gdb.config"

cman() {
	man -s "2,3,3p,2x,3x,7" "$*"
}

x() {
	./build.sh
}
xd() {
	./debug.sh
}

alias size_here="du -sh .[^.]* * 2>/dev/null | sort -hr"

reload() {
	# shellcheck source=aliases.sh
	source "$here/aliases.sh"
}

# ensure bash completions are loaded
if [ -f /etc/profile.d/bash_completion.sh ]; then
	# System-provided optional completion support.
	# shellcheck source=/dev/null
	source /etc/profile.d/bash_completion.sh
fi

# load git aliases
# shellcheck source=git-aliases.sh
# The runtime-resolved sibling path works when aliases.sh is symlinked.
# shellcheck disable=SC1091
source "$here/git-aliases.sh"

# Trailing space: bash then alias-expands the word after `sudo`.
alias sudo='sudo '

# util script router: `util <command> [args]` -> util/<command>[.sh], reached as `util` on PATH
# (~/.local/sbin/util, a declared host-baseline command link: fleet-deploy commands), never as an alias.
if [ -f "$here/util/dispatch.sh" ]; then
	# `vol`/`volume` run `util` from PATH.
	alias vol='util volume'
	alias volume='util volume'
	if [ -f "$here/util/completions.sh" ]; then
		# shellcheck source=util/completions.sh
		# The runtime-resolved sibling path works when aliases.sh is symlinked.
		# shellcheck disable=SC1091
		source "$here/util/completions.sh"
	fi
fi

if [ -f /etc/debian_version ]; then
	# shellcheck source=debian-aliases.sh
	# The runtime-resolved sibling path works when aliases.sh is symlinked.
	# shellcheck disable=SC1091
	source "$here/debian-aliases.sh"
fi

if [ -f /etc/gentoo-release ]; then
	# shellcheck source=gentoo-aliases.sh
	# The runtime-resolved sibling path works when aliases.sh is symlinked.
	# shellcheck disable=SC1091
	source "$here/gentoo-aliases.sh"
fi

if [ -f "$here/private/aliases.sh" ]; then
	# Optional private overlay is deliberately not tracked.
	# shellcheck source=/dev/null
	source "$here/private/aliases.sh"
fi
